/** Bounded cooperative execution records. This verifier never calls an adapter,
 * executes code, proves identity/authenticity or changes acceptance/payment. */
export const DELIVERY_STAGES = ["submit", "stored_record", "fresh_readback", "email_receipt"] as const;
export type DeliveryStage = typeof DELIVERY_STAGES[number];
export type DeliveryStageStatus = "matched" | "mismatch" | "unknown" | "unsupported";
export type DeliveryStagePlan = {
  schema: "pbp-delivery-stage-plan-v1"; runId: string; syntheticOnly: true;
  scope: {projectId: string; deliveryId: string; criterionId: string; sourceRevision: string; requirement: string};
  payloadDigest: string;
  stages: {stage: DeliveryStage; coverage: "adapter" | "manual" | "unsupported"}[];
};
type NativeRecord = {recordId: string; payloadDigest: string};
type Base = {outcome: "observed"; runId: string; sourceRevision: string};
export type DeliveryStageObservation =
  | {outcome: "unsupported"}
  | {outcome: "unknown"; reason: "adapter_error" | "timeout" | "manual_required" | "prior_result_unknown"}
  | (Base & {stage: "submit"; accepted: boolean; operationId: string; record: NativeRecord | null})
  | (Base & {stage: "stored_record"; reader: "native_store"; connectionId: string; record: NativeRecord | null})
  | (Base & {stage: "fresh_readback"; reader: "fresh_connection"; connectionId: string; record: NativeRecord | null})
  | (Base & {stage: "email_receipt"; transport: "test_sink" | "test_inbox"; receipt: (NativeRecord & {receiptId: string}) | null});
export type DeliveryStageRow = {stage: DeliveryStage; observation: DeliveryStageObservation; status: DeliveryStageStatus; reason: string};
export type DeliveryStageReport = {
  schema: "pbp-delivery-stage-report-v1"; evidenceLevel: "cooperative_adapter_observations";
  plan: DeliveryStagePlan; rows: DeliveryStageRow[]; summary: Record<DeliveryStageStatus, number>; digest: string;
};
export const DELIVERY_STAGE_REPORT_BYTE_LIMIT = 64 * 1024;
const identifier = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$/u;
const sha = /^[a-f0-9]{64}$/u;
function fail():never { throw new Error("INVALID_DELIVERY_STAGE_EVIDENCE"); }
function bounded(value: unknown): void {
  let nodes=0,chars=0; const ancestors=new Set<object>();
  function visit(v:unknown,depth:number):void {
    if (++nodes>3000||depth>12) fail();
    if (typeof v==="string") {chars+=v.length;if(chars>DELIVERY_STAGE_REPORT_BYTE_LIMIT)fail();return;}
    if(v===null||typeof v==="boolean")return;
    if(typeof v==="number"){if(!Number.isFinite(v))fail();return;}
    if(!v||typeof v!=="object"||ancestors.has(v))fail();
    if(Array.isArray(v)){if(v.length>100||Object.keys(v).length!==v.length)fail();}
    else if(![Object.prototype,null].includes(Object.getPrototypeOf(v)))fail();
    ancestors.add(v);
    for(const k of Reflect.ownKeys(v)){
      if(Array.isArray(v)&&k==="length")continue;
      const d=Object.getOwnPropertyDescriptor(v,k)!;
      if(typeof k!=="string"||["__proto__","constructor","prototype"].includes(k)||!("value" in d)||!d.enumerable)fail();
      chars+=k.length;visit(d.value,depth+1);
    }
    ancestors.delete(v);
  }
  visit(value,0);if(new TextEncoder().encode(JSON.stringify(value)).byteLength>DELIVERY_STAGE_REPORT_BYTE_LIMIT)fail();
}
function object(v:unknown,keys:string[]):Record<string,unknown>{
  if(!v||typeof v!=="object"||Array.isArray(v)||![Object.prototype,null].includes(Object.getPrototypeOf(v)))fail();
  if(Object.keys(v).sort().join("|")!==[...keys].sort().join("|"))fail();return v as Record<string,unknown>;
}
function id(v:unknown):void{if(typeof v!=="string"||!identifier.test(v))fail();}
function digest(v:unknown):void{if(typeof v!=="string"||!sha.test(v))fail();}
export function validateDeliveryStagePlan(value:unknown):DeliveryStagePlan{
  bounded(value);const p=object(value,["schema","runId","syntheticOnly","scope","payloadDigest","stages"]);
  if(p.schema!=="pbp-delivery-stage-plan-v1"||p.syntheticOnly!==true)fail();id(p.runId);digest(p.payloadDigest);
  const s=object(p.scope,["projectId","deliveryId","criterionId","sourceRevision","requirement"]);
  for(const k of ["projectId","deliveryId","criterionId","sourceRevision"])id(s[k]);
  if(typeof s.requirement!=="string"||!s.requirement.trim()||s.requirement.length>4000||/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/u.test(s.requirement))fail();
  if(!Array.isArray(p.stages)||p.stages.length!==4)fail();
  p.stages.forEach((v,i)=>{const row=object(v,["stage","coverage"]);if(row.stage!==DELIVERY_STAGES[i]||!["adapter","manual","unsupported"].includes(String(row.coverage)))fail();});
  return structuredClone(value) as DeliveryStagePlan;
}
function nativeRecord(v:unknown,receipt=false):void{
  if(v===null)return;const r=object(v,receipt?["recordId","payloadDigest","receiptId"]:["recordId","payloadDigest"]);id(r.recordId);digest(r.payloadDigest);if(receipt)id(r.receiptId);
}
export function validateDeliveryStageObservation(stage:DeliveryStage,value:unknown):DeliveryStageObservation{
  bounded(value);if(!DELIVERY_STAGES.includes(stage)||!value||typeof value!=="object"||Array.isArray(value))fail();
  const outcome=(value as {outcome?:unknown}).outcome;
  if(outcome==="unsupported")object(value,["outcome"]);
  else if(outcome==="unknown"){
    const o=object(value,["outcome","reason"]);if(!["adapter_error","timeout","manual_required","prior_result_unknown"].includes(String(o.reason)))fail();
  }else{
    const extra=stage==="submit"?["accepted","operationId","record"]:stage==="email_receipt"?["transport","receipt"]:["reader","connectionId","record"];
    const o=object(value,["outcome","runId","sourceRevision","stage",...extra]);
    if(o.outcome!=="observed"||o.stage!==stage)fail();id(o.runId);id(o.sourceRevision);
    if(stage==="submit"){if(typeof o.accepted!=="boolean")fail();id(o.operationId);nativeRecord(o.record);}
    else if(stage==="email_receipt"){if(!["test_sink","test_inbox"].includes(String(o.transport)))fail();nativeRecord(o.receipt,true);}
    else{if(o.reader!==(stage==="stored_record"?"native_store":"fresh_connection"))fail();id(o.connectionId);nativeRecord(o.record);}
  }
  return structuredClone(value) as DeliveryStageObservation;
}
function result(plan:DeliveryStagePlan,stage:DeliveryStage,o:DeliveryStageObservation,previous:DeliveryStageRow[]):Pick<DeliveryStageRow,"status"|"reason">{
  const coverage=plan.stages.find(p=>p.stage===stage)!.coverage;
  if(coverage!=="adapter")return {status:coverage==="manual"?"unknown":"unsupported",reason:coverage==="manual"?"manual_required":"stage_not_supported"};
  if(o.outcome==="unsupported")return {status:"unsupported",reason:"adapter_not_supported"};
  if(o.outcome==="unknown")return {status:"unknown",reason:o.reason};
  if(o.runId!==plan.runId||o.sourceRevision!==plan.scope.sourceRevision)return {status:"mismatch",reason:"wrong_run_or_revision"};
  const submitted=previous.find(r=>r.stage==="submit"),submitObservation=submitted?.observation;
  const record=o.stage==="email_receipt"?o.receipt:o.record;
  if(o.stage==="submit"&&(!o.accepted||!record))return {status:"mismatch",reason:"submission_not_accepted"};
  if(!record)return {status:"mismatch",reason:o.stage==="email_receipt"?"receipt_missing":"record_missing"};
  if(record.payloadDigest!==plan.payloadDigest)return {status:"mismatch",reason:"payload_differs"};
  if(stage!=="submit"){
    if(submitted?.status!=="matched"||submitObservation?.outcome!=="observed"||submitObservation.stage!=="submit"||!submitObservation.record)return {status:"unknown",reason:"submission_not_established"};
    if(record.recordId!==submitObservation.record.recordId)return {status:"mismatch",reason:"record_identity_differs"};
  }
  if(o.stage==="fresh_readback"){
    const stored=previous.find(r=>r.stage==="stored_record")?.observation;
    if(stored?.outcome!=="observed"||stored.stage!=="stored_record")return {status:"unknown",reason:"stored_reader_unavailable"};
    if(stored.connectionId===o.connectionId)return {status:"mismatch",reason:"reader_not_fresh"};
  }
  return {status:"matched",reason:o.stage==="email_receipt"?"cooperative_test_receipt_matches":"cooperative_record_matches"};
}
function canonical(value:unknown):string{return JSON.stringify(value,(_key,v)=>v&&typeof v==="object"&&!Array.isArray(v)?Object.fromEntries(Object.entries(v).sort(([a],[b])=>a<b?-1:a>b?1:0)):v);}
async function hash(value:unknown):Promise<string>{return [...new Uint8Array(await crypto.subtle.digest("SHA-256",new TextEncoder().encode(canonical(value))))].map(n=>n.toString(16).padStart(2,"0")).join("");}
export async function createDeliveryStageReport(planInput:unknown,observations:unknown[]):Promise<DeliveryStageReport>{
  const plan=validateDeliveryStagePlan(planInput);if(!Array.isArray(observations)||observations.length!==4)fail();
  const rows:DeliveryStageRow[]=[];
  for(let i=0;i<4;i++){const stage=DELIVERY_STAGES[i],observation=validateDeliveryStageObservation(stage,observations[i]);if(plan.stages[i].coverage==="unsupported"&&observation.outcome!=="unsupported"||plan.stages[i].coverage==="manual"&&(observation.outcome!=="unknown"||observation.reason!=="manual_required"))fail();rows.push({stage,observation,...result(plan,stage,observation,rows)});}
  const summary:Record<DeliveryStageStatus,number>={matched:0,mismatch:0,unknown:0,unsupported:0};for(const row of rows)summary[row.status]++;
  const body={schema:"pbp-delivery-stage-report-v1" as const,evidenceLevel:"cooperative_adapter_observations" as const,plan,rows,summary};
  return {...body,digest:await hash(body)};
}
export async function validateDeliveryStageReport(value:unknown):Promise<DeliveryStageReport>{
  bounded(value);const v=object(value,["schema","evidenceLevel","plan","rows","summary","digest"]);
  if(v.schema!=="pbp-delivery-stage-report-v1"||v.evidenceLevel!=="cooperative_adapter_observations"||!Array.isArray(v.rows)||v.rows.length!==4)fail();
  v.rows.forEach((r,i)=>{const row=object(r,["stage","observation","status","reason"]);if(row.stage!==DELIVERY_STAGES[i])fail();});
  const expected=await createDeliveryStageReport(v.plan,v.rows.map(r=>(r as Record<string,unknown>).observation));
  if(canonical(expected)!==canonical(value))fail();return expected;
}

import {DELIVERY_STAGES,createDeliveryStageReport,validateDeliveryStageObservation,validateDeliveryStagePlan,type DeliveryStage,type DeliveryStageObservation,type DeliveryStagePlan,type DeliveryStageReport} from "./delivery-stage-evidence.ts";
export type DeliveryStageAdapter = Partial<Record<DeliveryStage,(context:{plan:DeliveryStagePlan;previous:readonly DeliveryStageObservation[];signal:AbortSignal})=>Promise<unknown>>>;
/** Explicit cooperative adapter invocation only. No URL discovery, model calls,
 * writes outside adapters, automatic retries or acceptance authority. */
export function createDeliveryStageProbe(adapter:DeliveryStageAdapter,options:{timeoutMs?:number}={}){
  const timeoutMs=options.timeoutMs??5000;
  if(!adapter||typeof adapter!=="object"||Array.isArray(adapter)||Reflect.ownKeys(adapter).some(k=>typeof k!=="string"||!DELIVERY_STAGES.includes(k as DeliveryStage)||!("value" in Object.getOwnPropertyDescriptor(adapter,k)! )||typeof adapter[k as DeliveryStage]!=="function")||!Number.isInteger(timeoutMs)||timeoutMs<1||timeoutMs>30000)throw Error("INVALID_STAGE_PROBE_ADAPTER");
  let busy=false,closed=false;
  return {
    async run(input:unknown):Promise<DeliveryStageReport>{
      if(closed)throw Error("STAGE_PROBE_EXTERNAL_OUTCOME_UNKNOWN");if(busy)throw Error("STAGE_PROBE_BUSY");busy=true;
      try{
        const plan=validateDeliveryStagePlan(input),observations:DeliveryStageObservation[]=[];
        let unresolvedSideEffect=false;
        for(const {stage,coverage}of plan.stages){
          if(coverage!=="adapter"){observations.push(coverage==="manual"?{outcome:"unknown",reason:"manual_required"}:{outcome:"unsupported"});continue;}
          if(unresolvedSideEffect){observations.push({outcome:"unknown",reason:"prior_result_unknown"});continue;}
          const operation=adapter[stage];if(!operation){observations.push({outcome:"unsupported"});continue;}
          const controller=new AbortController();let timer:ReturnType<typeof setTimeout>|undefined;
          try{
            const timeout=new Promise<never>((_,reject)=>{timer=setTimeout(()=>{controller.abort();reject(Error("STAGE_TIMEOUT"));},timeoutMs);});
            const pending=Promise.resolve().then(()=>operation({plan:structuredClone(plan),previous:structuredClone(observations),signal:controller.signal}));
            const raw=await Promise.race([pending,timeout]);
            const observation=validateDeliveryStageObservation(stage,raw);observations.push(observation);
            if(observation.outcome==="unknown"){unresolvedSideEffect=true;closed=true;}
          }catch(error){observations.push({outcome:"unknown",reason:error instanceof Error&&error.message==="STAGE_TIMEOUT"?"timeout":"adapter_error"});unresolvedSideEffect=true;closed=true;}
          finally{if(timer)clearTimeout(timer);}
        }
        return await createDeliveryStageReport(plan,observations);
      }finally{busy=false;}
    }
  };
}

#!/usr/bin/env node
/** Explicitly executes a seller-selected LOCAL adapter. Never import a browser
 * upload. Use only reviewed adapters against isolated synthetic staging data. */
import {readFile,writeFile,lstat,realpath} from 'node:fs/promises';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import {createDeliveryStageProbe} from '../lib/delivery-stage-probe.ts';
import {validateDeliveryStagePlan} from '../lib/delivery-stage-evidence.ts';
export async function runDeliveryStageProbeCli(args){
  if(args.length!==6||args[0]!=='--plan'||args[2]!=='--adapter'||args[4]!=='--output')throw Error('USAGE: --plan <local-plan.json> --adapter <reviewed-local-adapter.mjs> --output <new-report.json>');
  let planFile=path.resolve(args[1]),adapterFile=path.resolve(args[3]);const output=path.resolve(args[5]);
  for(const [file,limit]of [[planFile,16384],[adapterFile,65536]]){const stat=await lstat(file);if(!stat.isFile()||stat.isSymbolicLink()||stat.size>limit)throw Error('INVALID_LOCAL_STAGE_INPUT');}
  planFile=await realpath(planFile);adapterFile=await realpath(adapterFile);
  // Validate all declarative input and reserve a new output before any imported
  // module can execute. A module is code, not a trusted evidence packet.
  const plan=validateDeliveryStagePlan(JSON.parse(await readFile(planFile,'utf8')));
  const handle=await (await import('node:fs/promises')).open(output,'wx',0o600);
  try{
    const module=await import(pathToFileURL(adapterFile).href);
    if(typeof module.createAdapter!=='function')throw Error('LOCAL_ADAPTER_FACTORY_REQUIRED');
    const adapter=await module.createAdapter({plan:structuredClone(plan)});
    try{const report=await createDeliveryStageProbe(adapter.stages).run(plan);await handle.writeFile(JSON.stringify(report,null,2)+'\n');return {recorded:true,reportDigest:report.digest,summary:report.summary,realModelCalls:0};}
    finally{if(typeof adapter.close==='function')await adapter.close();}
  }finally{await handle.close();}
}
if(process.argv[1]&&import.meta.url===pathToFileURL(path.resolve(process.argv[1])).href){
 try{console.log(JSON.stringify(await runDeliveryStageProbeCli(process.argv.slice(2)),null,2));}
 catch(error){console.error(error?.code==='EEXIST'?'STAGE_REPORT_ALREADY_EXISTS':error instanceof Error&&/^[A-Z][A-Z0-9_: <>().-]{0,220}$/u.test(error.message)?error.message:'STAGE_PROBE_FAILED');process.exitCode=1;}
}

import http from 'node:http';
import {DatabaseSync} from 'node:sqlite';
import {createHash} from 'node:crypto';
const profiles=['fixed','no-store','wrong-readback','no-email'];
/** Disposable loopback-only native enquiry app. No checker/verdict imports. */
export async function startStageStaging({database,profile='fixed'}){
 if(!profiles.includes(profile))throw Error('Unknown staging profile');
 const db=new DatabaseSync(database);db.exec('CREATE TABLE IF NOT EXISTS enquiries (id TEXT PRIMARY KEY, marker TEXT NOT NULL, subject TEXT NOT NULL, message TEXT NOT NULL, payload_digest TEXT NOT NULL); CREATE TABLE IF NOT EXISTS test_mail (id TEXT PRIMARY KEY, record_id TEXT NOT NULL, marker TEXT NOT NULL, subject TEXT NOT NULL, message TEXT NOT NULL, payload_digest TEXT NOT NULL)');
 const send=(response,status,body)=>{response.writeHead(status,{'content-type':'application/json'});response.end(JSON.stringify(body));};
 let sequence=0;
 const server=http.createServer(async(request,response)=>{
  try{
   const url=new URL(request.url,'http://127.0.0.1');
   if(request.method==='POST'&&url.pathname==='/enquiries'){
    let body='';for await(const chunk of request){body+=chunk;if(body.length>4096){send(response,413,{error:'too-large'});return;}}
    const input=JSON.parse(body);
    if(Object.keys(input).sort().join('|')!=='marker|message|subject'||!/^stage-[a-z0-9-]{1,80}$/u.test(input.marker)||input.subject!=='PBP synthetic enquiry'||input.message!=='Synthetic staged delivery test'){send(response,400,{error:'synthetic-only'});return;}
    const id='enquiry-'+(++sequence),payloadDigest=createHash('sha256').update(JSON.stringify({subject:input.subject,message:input.message})).digest('hex');
    if(profile!=='no-store')db.prepare('INSERT INTO enquiries VALUES (?,?,?,?,?)').run(id,input.marker,input.subject,input.message,payloadDigest);
    if(profile!=='no-email')db.prepare('INSERT INTO test_mail VALUES (?,?,?,?,?,?)').run('mail-'+sequence,id,input.marker,input.subject,input.message,payloadDigest);
    send(response,201,{id,marker:input.marker,subject:input.subject,message:input.message});return;
   }
   send(response,404,{error:'not-found'});
  }catch{send(response,500,{error:'native-operation-failed'});}
 });
 await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(0,'127.0.0.1',resolve);});
 return {origin:'http://127.0.0.1:'+server.address().port,
  readStored(recordId){return db.prepare('SELECT id,marker,subject,message,payload_digest FROM enquiries WHERE id=?').get(recordId)??null;},
  readFresh(recordId){const connection=new DatabaseSync(database,{readOnly:true});try{const record=connection.prepare('SELECT id,marker,subject,message,payload_digest FROM enquiries WHERE id=?').get(recordId)??null;return profile==='wrong-readback'&&record?{...record,id:'different-enquiry'}:record;}finally{connection.close();}},
  readInbox(recordId){return db.prepare('SELECT id,record_id,marker,subject,message,payload_digest FROM test_mail WHERE record_id=?').get(recordId)??null;},
  async close(){await new Promise(resolve=>server.close(resolve));db.close();}
 };
}

import {mkdtemp,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import path from 'node:path';
import {randomUUID,createHash} from 'node:crypto';
import {startStageStaging} from './server.mjs';
/** This adapter owns its native connection/HTTP details. The runner has no
 * endpoint discovery and never interprets a success page as a stored record. */
export async function createAdapter({plan,profile='fixed'}){
 const dir=await mkdtemp(path.join(tmpdir(),'pbp-stage-staging-'));
 const native=await startStageStaging({database:path.join(dir,'native.sqlite'),profile});let recordId;
 const base=stage=>({outcome:'observed',stage,runId:plan.runId,sourceRevision:plan.scope.sourceRevision});
 const actualDigest=row=>createHash('sha256').update(JSON.stringify({subject:row.subject,message:row.message})).digest('hex');
 const record=row=>row?{recordId:row.id,payloadDigest:actualDigest(row)}:null;
 return {stages:{
  async submit({signal}){const r=await fetch(native.origin+'/enquiries',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({marker:plan.runId,subject:'PBP synthetic enquiry',message:'Synthetic staged delivery test'}),signal});const body=await r.json();recordId=body.id;return {...base('submit'),runId:body.marker??plan.runId,accepted:r.status===201,operationId:'native-enquiry-post',record:r.status===201?{recordId:body.id,payloadDigest:actualDigest(body)}:null};},
  async stored_record(){const row=native.readStored(recordId);return {...base('stored_record'),runId:row?.marker??plan.runId,connectionId:'writer-native-connection',reader:'native_store',record:record(row)};},
  async fresh_readback(){const row=native.readFresh(recordId);return {...base('fresh_readback'),runId:row?.marker??plan.runId,connectionId:'fresh-'+randomUUID(),reader:'fresh_connection',record:record(row)};},
  async email_receipt(){const row=native.readInbox(recordId);return {...base('email_receipt'),runId:row?.marker??plan.runId,transport:'test_sink',receipt:row?{receiptId:row.id,recordId:row.record_id,payloadDigest:actualDigest(row)}:null};}
 },async close(){await native.close();await rm(dir,{recursive:true,force:true});}};
}
